-- Attendance exactly-one invariant (docs/PHASE_5_MIGRATION_REPORT.md S6, Phase 2):
-- every attendance row has exactly one of student_class_enrollment_id OR
-- staff_person_id set. The STUDENT partial-unique is expressed by the Prisma
-- NULL-DISTINCT @@unique([tenantId, studentClassEnrollmentId, subjectId, date]).
ALTER TABLE "attendance" ADD CONSTRAINT "attendance_participant_check"
  CHECK (
    ("student_class_enrollment_id" IS NOT NULL AND "staff_person_id" IS NULL)
    OR ("student_class_enrollment_id" IS NULL AND "staff_person_id" IS NOT NULL)
  );
